<header class="admin-top"><div><p>Automation</p><h1>Jobs & Scheduler</h1></div><div class="admin-inline"><button class="admin-secondary" data-scheduler-tick>Scheduler tick</button><button class="admin-primary" data-worker-run>Run worker once</button></div></header>
<section class="admin-panel"><table class="admin-table"><thead><tr><th>Job</th><th>Subject</th><th>Status</th><th>Attempts</th><th>Available</th><th>Error</th></tr></thead><tbody><?php foreach($jobs as $j):?><tr><td><strong><?=pm_e($j['type']??'')?></strong><small><?=pm_e($j['id']??'')?></small></td><td><?=pm_e($j['subject_id']??'—')?></td><td><span class="status <?=pm_e($j['status']??'queued')?>"><?=pm_e(strtoupper($j['status']??'queued'))?></span></td><td><?= (int)($j['attempts']??0) ?>/<?= (int)($j['max_attempts']??5) ?></td><td><?=pm_e($j['available_at']??'—')?></td><td class="error-text"><?=pm_e($j['last_error']??'')?></td></tr><?php endforeach;?></tbody></table><?php if(!$jobs):?><div class="admin-empty">Queue is empty. Run the scheduler after enabling a source.</div><?php endif;?></section>
